    def _get_working_prefix_path(self, host_home_path):
        robot5gws_home = '/Auto5G/'
        robotws5g_home = '/robotws/'
        robotlte_home = '/MN/UTE/robotlte/'
        robotlte_temp_home = '/robotlte/'  # This temp path will be replaced with the use of robotlte_home
        docker_mode_home = '/test_repository/'
        robot5gws_middle_path = 'testsuite/TRS/Bangalore/E2E_BTS_TRS_FW/'
        robotws5g_middle_path = 'testsuite/Bangalore/TRS/E2E_BTS_TRS_FW/'
        robotlte_middle_path = 'testsuite/WMP/E2E_BTS_TRS_FW/'
        middle_paths = [robotws5g_middle_path, robot5gws_middle_path, robotlte_middle_path]
        home_paths = [robotws5g_home, robot5gws_home, robotlte_home, robotlte_temp_home, docker_mode_home]
        for home_path in home_paths:
            for middle_path in middle_paths:
                prefix_path = '{}{}{}'.format(host_home_path, home_path, middle_path)
                if os.path.exists(prefix_path):
                    return prefix_path
        return None

    def _make_symlinks(self, fw_user_path_full, home_dir):
        fw_user_path_symlink = '{}/fw_user_path'.format(home_dir)
        if os.path.islink(fw_user_path_symlink):
            print("fw_user_path already exist at {}.".format(home_dir))
            # os.remove(fw_user_path_symlink)
        else:
            os.symlink(fw_user_path_full, fw_user_path_symlink)
        print("fw_user_path_symlink is {}".format(fw_user_path_symlink))
        # Framework path soft-link creation is not required for package approach
        # fw_path_symlink = '{}/fw_path'.format(home_dir)
        # if not os.environ.get('CI_PROJECT_DIR'):
        #     if os.path.islink(fw_path_symlink):
        #         print("fw_path already exist at {}.".format(home_dir))
        #         # os.remove(fw_path_symlink)
        #     else:
        #         os.symlink(fw_path_full, fw_path_symlink)
        return fw_user_path_symlink

    def add_to_pythonpath(self, home_dir):
        """Adds fw_path and fw_user_path to the PYTHONPATH.
        Updated PYTHONPATH is available in the current session ONLY"""
        chkout_command = "grep \"export PYTHONPATH={}/fw_user_path\" ~/.bashrc".format(home_dir)
        out = subprocess.Popen(chkout_command, shell=True, stdout=subprocess.PIPE)
        stdout, stderr = out.communicate()
        if not stdout:
            print("Adding PYTHONPATH")
            subprocess.check_output("echo export PYTHONPATH=$PYTHONPATH:{}/fw_user_path >> ~/.bashrc".format(home_dir),
                                    shell=True)
        else:
            print("PYTHONPATH already added into .bashrc")
